import java.io.File;
import java.nio.file.Path;

public class PathTraversalExample {
    public static void main(String[] args) {
        // This code is vulnerable to path traversal because it uses user input directly
        // without sanitization, allowing an attacker to access files outside the intended directory.
        String userInput = "../etc/passwd"; 
        File file = new File("/var/www/uploads/" + userInput);

        // The file object now points to /etc/passwd, exposing sensitive system data
        if (file.exists()) {
            System.out.println("File found: " + file.getAbsolutePath());
        }
    }
}
