import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class PathTraversalFixed {
    public static void main(String[] args) {
        String userInput = "../etc/passwd";

        // Define the base directory and resolve the user input safely
        Path basePath = Paths.get("/var/www/uploads");
        Path safePath = basePath.resolve(userInput).normalize();

        // Ensure the resolved path remains within the base directory
        // This prevents path traversal attacks by validating the final absolute path
        if (!safePath.startsWith(basePath)) {
            throw new SecurityException("Access denied: Path traversal detected");
        }

        File file = safePath.toFile();

        if (file.exists()) {
            System.out.println("File found securely: " + file.getAbsolutePath());
        }
    }
}
